  "electrical": T.Electrical;
  "electrical_command": T.ElectricalCommand;
  "electrical_result": T.ElectricalResult;
  "health": T.Health;
  "heatmap": T.Heatmap;
  "info": T.Info;
  "network": T.Network;
  "network_orders": T.NetworkOrders;
  "node_control_command": T.NodeControlCommand;
  "node_control_result": T.NodeControlResult;
